package com.securedeploy.project.progress;
import com.securedeploy.analysis.typescript.*;import java.util.*;import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class EngineTransitionComparisonTest {
 final ProgressComparisonEngineTest fixtures=new ProgressComparisonEngineTest();final ProgressComparisonEngine engine=new ProgressComparisonEngine();
 final String original="import express from 'express';const app=express();app.get('/',(req,res)=>{\n return res.json({ok:true,key:process.env.API_SECRET});\n});";
 ServerAnalysisSnapshot snapshot(String code){return new TypeScriptServerAnalyzer(new TypeScriptAnalysisProperties()).analyze(new com.securedeploy.project.model.ProjectStructure(java.nio.file.Path.of("/synthetic-only"),List.of(new com.securedeploy.project.model.ProjectFile(java.nio.file.Path.of("web.mjs"),"web.mjs",com.securedeploy.project.model.ProjectFileType.JAVASCRIPT,code.lines().toList()),new com.securedeploy.project.model.ProjectFile(java.nio.file.Path.of("package.json"),"package.json",com.securedeploy.project.model.ProjectFileType.PACKAGE_JSON,List.of("{\"type\":\"module\",\"dependencies\":{\"express\":\"4.21.2\"}}")))));}
 com.securedeploy.persistence.entity.ReviewEntity review(long id,String code,String version){var r=fixtures.review(id,fixtures.sca(com.securedeploy.sca.model.ScaResult.Status.COMPLETE,List.of()));var s=snapshot(code);
 // Serialized legacy-shape control only, not an actual v52 worker execution.
 if(!version.equals("ts-server-v59")){var c=new ServerAnalysisConverter();s=c.convertToEntityAttribute(c.convertToDatabaseColumn(s).replace("ts-server-v59",version).replace("flow:","legacy-flow:"));}
 r.attachServerAnalysis(s);var e=new ComparisonEvidence(1,"SHA256_BYTES_V1",Map.of("web.mjs",ProgressComparisonEngineTest.digest(code)),true,Map.of("backend",version,"typescript",version,"python","py-test","typescriptArtifact",version,"pythonArtifact","py-test","typescriptConfiguration","true:8","pythonConfiguration","true:8","typescriptParser","6.0.3","pythonParser","NOT_EXECUTED"));
 r.attachComparisonContext(new ComparisonContext(1,id==1?null:1L,version,true,List.of("web.mjs"),null,e));return r;}
 @Test void sameCodeDifferentEngineDoesNotResolveOrIntroduceRiskById(){var a=review(1,original,"ts-server-v52");var b=review(2,original,"ts-server-v59");var raw=a.getServerAnalysis();var p=engine.compare(a,b);assertThat(a.getServerAnalysis().validatedFindings().get(0).findingId()).isNotEqualTo(b.getServerAnalysis().validatedFindings().get(0).findingId());assertThat(p.basis().engineState()).isEqualTo("CHANGED");assertThat(p.basis().sourceState()).isEqualTo("SAME_ANALYZED_INPUT");assertThat(p.basis().flowChanges()).singleElement().satisfies(e->assertThat(e.status()).isEqualTo("OBSERVED_BOTH"));assertThat(p.counts()).containsEntry(ReviewProgressSnapshot.Change.RESOLVED,0L).containsEntry(ReviewProgressSnapshot.Change.NEW,0L);assertThat(a.getServerAnalysis()).isSameAs(raw);}
 @Test void editedCodeSameEnginePreservesEntryAndReportsLimitedNonObservation(){var a=review(1,original,"ts-server-v59");var b=review(2,original.replace(",key:process.env.API_SECRET",""),"ts-server-v59");var p=engine.compare(a,b);assertThat(p.basis().engineState()).isEqualTo("SAME");assertThat(p.basis().flowChanges()).singleElement().satisfies(e->assertThat(e.status()).isEqualTo("NOT_REOBSERVED_AFTER_EDIT"));assertThat(p.counts()).containsEntry(ReviewProgressSnapshot.Change.RESOLVED,0L);}
 @Test void editedCodeAndEngineNeverConfirmResolution(){var p=engine.compare(review(1,original,"ts-server-v52"),review(2,original.replace(",key:process.env.API_SECRET",""),"ts-server-v59"));assertThat(p.basis().engineState()).isEqualTo("CHANGED");assertThat(p.basis().flowChanges()).allSatisfy(e->assertThat(e.status()).isEqualTo("UNAVAILABLE"));assertThat(p.counts()).containsEntry(ReviewProgressSnapshot.Change.RESOLVED,0L);}
 @Test void disappearingEntryAndUnknownCallsNeverProduceEditSuccess(){for(var body:List.of(original.replace("app.get(","unregistered("),original.replace("process.env.API_SECRET","hide(process.env.API_SECRET)"))){var p=engine.compare(review(1,original,"ts-server-v59"),review(2,body,"ts-server-v59"));assertThat(p.basis().flowChanges()).noneMatch(e->e.status().equals("NOT_REOBSERVED_AFTER_EDIT"));}}
 @Test void oldHashlessSnapshotsAreReadableButCannotSupplyNegativeEvidence(){var a=fixtures.review(1,fixtures.sca(com.securedeploy.sca.model.ScaResult.Status.COMPLETE,List.of()),fixtures.code("A",1));var b=fixtures.review(2,fixtures.sca(com.securedeploy.sca.model.ScaResult.Status.COMPLETE,List.of()));b.attachComparisonContext(new ComparisonContext(1,1L,"test-v1",true,List.of("application.yml")));var p=engine.compare(a,b);assertThat(p.counts()).containsEntry(ReviewProgressSnapshot.Change.RESOLVED,0L);assertThat(p.basis().engineState()).isEqualTo("UNKNOWN");}
 @Test void unchangedInputNeverResolvesACatalogWarning(){var a=fixtures.review(1,fixtures.sca(com.securedeploy.sca.model.ScaResult.Status.COMPLETE,List.of()),fixtures.code("A",1));var b=fixtures.review(2,fixtures.sca(com.securedeploy.sca.model.ScaResult.Status.COMPLETE,List.of()));b.attachComparisonContext(a.getComparisonContext().withBaseline(1L));assertThat(engine.compare(a,b).counts()).containsEntry(ReviewProgressSnapshot.Change.RESOLVED,0L);}
 @Test void legacyRawEvidenceIsNotClaimedAsNewEngineEvidence()throws Exception{var a=review(1,original,"ts-server-v52");var b=review(2,original,"ts-server-v59");var converter=new ServerAnalysisConverter();var tree=(com.fasterxml.jackson.databind.node.ObjectNode)new com.fasterxml.jackson.databind.ObjectMapper().readTree(converter.convertToDatabaseColumn(a.getServerAnalysis()));tree.set("validatedFindings",new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode());var legacy=fixtures.review(1,fixtures.sca(com.securedeploy.sca.model.ScaResult.Status.COMPLETE,List.of()));legacy.attachComparisonContext(a.getComparisonContext());legacy.attachServerAnalysis(converter.convertToEntityAttribute(tree.toString()));assertThat(engine.compare(legacy,b).basis().flowChanges()).noneMatch(e->e.status().equals("ENGINE_EVIDENCE_ADDED"));}
}
